'use strict';
// Helio Bot — curated connector + plugin directory (offline half).
//
// Mirrors the shape of the desktop app's connector browser: every row carries
// the name a user recognises, a category, the auth kind, a one-line
// description, and the tools that installing it exposes to the agent.
//
// The dynamic half lives in `mcpregistry.js`, which pulls live servers from the
// official Model Context Protocol registry and merges them in at search time.
//
// Connector row: [id, name, category, auth, description, tools[], endpoint?]
//   auth      'oauth' (hosted sign-in) | 'apikey' (token pasted in settings) | 'none'
//   endpoint  optional { type: 'http' | 'sse', url } for public hosted MCP servers
// Plugin row:    [id, name, description, provides[], category?]
//
// Nothing here ships third-party code. Installing a row records intent and, when
// an endpoint exists, registers it with the MCP client so its tools go live.

